if (en.MoveNext())
{
	ConstructorInfo conInfo = en.Current;
	if (!en.MoveNext())
	{
		return conInfo;
	}
}

if (metadataType != null)
{
	attribute = ReflectionUtils.GetAttribute<T>(metadataType, true);
	if (attribute != null)
	{
		return attribute;
