if (targetType == typeof(Int128) || targetType == typeof(UInt128))
{
	BigInteger integer = initialValue is string text
		? BigInteger.Parse(text, NumberStyles.Integer, culture)
		: ToBigInteger(initialValue);
	value = FromBigInteger(integer, targetType);
	return true;
}

if (mantissaDigits < 19)
{
	mantissa = (10 * mantissa) + (ulong)(c - '0');
	if (mantissa > 0)
	{
		++mantissaDigits;
	}
}

if (offsetText.Length - startIndex > 5)
{
	if (ConvertUtils.Int32TryParse(offsetText.Chars, startIndex + 3, 2, out minutes) != ParseResult.Success)
	{
		offset = default;
		return false;
	}
}

if (enableParamArray)
{
	ParameterInfo lastParam = parameters[parameters.Length - 1];
	if (lastParam.ParameterType.IsArray && lastParam.IsDefined(typeof(ParamArrayAttribute)))
	{
		paramArrayType = lastParam.ParameterType.GetElementType();
	}
}

if (paramType.IsPrimitive())
{
	if (!types[i].IsPrimitive() || !CanConvertPrimitive(types[i], paramType))
	{
		// primitive parameter can only be assigned from compatible primitive type
		return false;
	}
}

if (fractionIndex < 0)
{
	if (int.TryParse(input, NumberStyles.Integer, formatProvider, out numerator))
	{
		result = new Ratio(numerator, 1);
		return true;
	}
}

else
{
	object columnValue = (reader.Value != null)
		? serializer.Deserialize(reader, column.DataType) ?? DBNull.Value
		: DBNull.Value;

	dr[columnName] = columnValue;
}

else
{
	// copy any remaining data to the beginning of the buffer if needed and reset positions
	if (remainingCharCount > 0)
	{
		BlockCopyChars(_chars, _charPos, _chars, 0, remainingCharCount);
	}
}

else
{
#if HAVE_INOTIFY_PROPERTY_CHANGING
	OnPropertyChanging(propertyName);
#endif
	Add(propertyName, value);
	OnPropertyChanged(propertyName);
}

else
{
	// no field name following dot in path and at end of base path/query
	if (followingDot && (atPathEnd || query))
	{
		throw new JsonException("Unexpected end while parsing path.");
	}
}

else if (currentChar == 't')
{
	if (Match("true"))
	{
		value = true;
		return true;
	}
}

else if (currentChar == 'f')
{
	if (Match("false"))
	{
		value = false;
		return true;
	}
}

else if (currentChar == 'n')
{
	if (Match("null"))
	{
		value = null;
		return true;
	}
}

else
{
	if (schema.AdditionalProperties != null)
	{
		_writer.WritePropertyName(JsonSchemaConstants.AdditionalPropertiesPropertyName);
		ReferenceOrWriteSchema(schema.AdditionalProperties);
	}
}

else
{
	if (schema.AdditionalItems != null)
	{
		_writer.WritePropertyName(JsonSchemaConstants.AdditionalItemsPropertyName);
		ReferenceOrWriteSchema(schema.AdditionalItems);
	}
}

else
{
	_genericCollectionDefinitionType = typeof(List<>).MakeGenericType(CollectionItemType);

	IsReadOnlyOrFixedSize = true;
	ShouldCreateWrapper = true;
	canDeserialize = HasParameterizedCreatorInternal;
}

else if (MemoryAdapter.IsMemoryType(NonNullableUnderlyingType))
{
	CollectionItemType = NonNullableUnderlyingType.GetGenericArguments()[0];
	MemoryAdapter = MemoryAdapter.Create(NonNullableUnderlyingType);
	_parameterizedCreator = arguments => MemoryAdapter.FromList((IList)arguments[0]!);
	IsReadOnlyOrFixedSize = true;
	canDeserialize = true;
}

else
{
	if (!digit29.HasValue)
	{
		digit29 = c;
	}
	++exponentFromMantissa;
}

else if (type1.IsByRef)
{
	type1 = type1.GetElementType();
	if (type1 == type2)
	{
		return 1;
	}
}

else
{
	type2 = type2.GetElementType();
	if (type2 == type1)
	{
		return -1;
	}
}

else
{
	using (JsonReader reader = new JValue(value).CreateReader())
	{
		Assert.Throws<OverflowException>(() => reader.ReadAsInt32());
		Assert.Same(value, reader.Value);
	}
}

else
{
	using (JsonReader reader = new JValue(value).CreateReader())
	{
		Assert.Throws<OverflowException>(() => reader.ReadAsDecimal());
		Assert.Same(value, reader.Value);
	}
}

private int CalculateSizeWithLength(int stringByteCount, bool includeSize)
{
	int baseSize = (includeSize)
		? 5 // size bytes + terminator
		: 1; // terminator

	return baseSize + stringByteCount;
}

