	else if (_readOnlyDictionary != null)
	{
		throw new NotSupportedException();
	}
#endif
	else
	{
		GenericDictionary.Add((TKey)key, (TValue)value!);
	}
}

void ICollection.CopyTo(Array array, int index)
{
	if (_dictionary != null)
